<script setup>
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import StatCard from '../components/StatCard.vue';import questions from '../data/questions.json';import {getCategoryStats,getSubcategoryStats} from '../utils/statistics'
const router=useRouter(),filter=ref('Semua');const subs=[...new Set(questions.filter(q=>q.kategori==='BTKV').map(q=>q.subkategori))];const stats=computed(()=>getCategoryStats('BTKV'));const rows=computed(()=>getSubcategoryStats('BTKV'));const strong=computed(()=>[...rows.value].sort((a,b)=>b.accuracy-a.accuracy)[0]?.subcategory||'Belum ada data');const weak=computed(()=>[...rows.value].sort((a,b)=>a.accuracy-b.accuracy)[0]?.subcategory||'Belum ada data');const start=(sub='',mode='')=>router.push({path:'/daily',query:{category:'BTKV',...(sub&&{subcategory:sub}),...(mode&&{mode})}})
const quick=['Sinonim','Antonim','Analogi','Silogisme','Pemahaman Bacaan']
</script>
<template><section class="page"><div class="hero"><div><span class="eyebrow">Bank verbal terstruktur</span><h1>BTKV</h1><p>Latihan BTKV untuk memperkuat kemampuan verbal, penalaran bahasa, analogi, sinonim, antonim, silogisme, dan pemahaman bacaan.</p></div><button class="btn xl" @click="start(filter==='Semua'?'':filter)">Mulai latihan BTKV</button></div><div class="stat-grid"><StatCard title="Soal BTKV dikerjakan" :value="stats.answered"/><StatCard title="Akurasi BTKV" :value="`${stats.accuracy}%`"/><StatCard title="Subkategori terkuat" :value="strong" tone="green"/><StatCard title="Subkategori terlemah" :value="weak" tone="amber"/></div><div class="card"><h2>Pilih fokus latihan</h2><div class="toolbar"><select v-model="filter"><option>Semua</option><option v-for="s in subs" :key="s">{{s}}</option></select></div><div class="button-grid"><button v-for="s in quick" :key="s" class="btn ghost" @click="start(s)">Latihan {{s}}</button><button class="btn ghost" @click="start('', 'wrong')">Ulangi Soal Salah</button><button class="btn ghost" @click="start('', 'bookmark')">Ulangi Soal Bookmark</button></div></div></section></template>
